    const extra = L3.xo > 0 && !p2.schaft ? [0.8, 0.84, 0.88, 0.92, 0.95, 0.975, 0.99, 1].map((k5) => L3.xo * k5) : [];
    const X5 = [...new Set([...X0, ...extra].map((x2) => Math.round(x2 * 1e6) / 1e6))].sort((a2, b4) => a2 - b4);
