      t5.push(`<rect x="46" y="37" width="8" height="10" rx="1" fill="#e5eef1" opacity="0.7" stroke="#8fa3aa" stroke-width="0.4"/><rect x="48" y="41" width="4" height="5" fill="#f6efe2"/><path d="M50 41 l0 -1.6" stroke="#333" stroke-width="0.4"/><path d="M50 37.2 q-1 1.4 0 2.4 q1 -1 0 -2.4" fill="#f6c453"/>`);
