    // ───────────── Schuhe (Q28-Leisten mit eigenen Parametern)
    t_skateschuh: schuh3("sneaker", "sneaker", "baumwolle", "schwarz", { sohle: 0.085, sohleFarbe: "#f4f3ef", profil: false, kappe: "gummi", lagen: [[0.05, 0.95, "#2a2c30"]], schnuerung: [0.36, 0.66, 6] }),
    t_hightop: schuh3("sneaker", "sneaker", "baumwolle", "rot", { schaft: 0.56, schaftSchnuerung: 4, schnuerung: [0.3, 0.64, 6], polsterRand: true, kappe: "gummi", sohleFarbe: "#f4f3ef", profil: false }),
    t_retrorunner: schuh3("sneaker", "sneaker", "leder", "grau", { zweiton: true, akzent: "#c8372f", overlays: true, sohleWelle: true, sohle: 0.1, sohleFarbe: "#ece6d8", lagen: [[0.1, 0.4, "#273659"]] }),
