      t5.push(`<path d="M13 58 Q14 32 50 30 Q86 32 87 58 Z" fill="${dunkel2(S.c, 0.5)}"/><path d="M20 34 Q34 27 50 27" stroke="#fff" stroke-width="1.4" opacity="0.25" fill="none"/>`);
      t5.push(flaeche5(S, glatt2([[6, 60], [20, 52], [50, 50], [80, 52], [94, 60], [84, 74], [50, 80], [16, 74]], true, 0.5), { ton: -0.04 }));
      t5.push(`<ellipse cx="50" cy="60" rx="38" ry="7.6" fill="${dunkel2(S.c, 0.55)}"/>`);
      for (const x2 of [36, 64]) t5.push(`<ellipse cx="${x2}" cy="59" rx="10" ry="5" fill="#dceef4" opacity="0.8" stroke="#2a2c30" stroke-width="1.4"/><path d="M${x2 - 6} 57.4 Q${x2 - 2} 55.6 ${x2 + 2} 56.4" stroke="#fff" stroke-width="0.8" opacity="0.7" fill="none"/>`);
      t5.push(`<path d="M46 58 Q50 55.6 54 58" stroke="#2a2c30" stroke-width="1.3" fill="none"/>`);
      t5.push(naht("M12 66 Q50 76 88 66", S, 0.8));
