  async function messen({ renderer, scene: scene2, camera, info, vorBild, anzahl: anzahl2 = 90 }) {
    if (!scene2 || !camera) throw new Error("Bitte zuerst ein Spiel starten.");
    const renderMs = [], frameMs = [], updateMs = [];
    let vorher = 0;
    const startGesamt = performance.now();
    for (let i = 0; i < anzahl2; i++) {
      if (i >= 5 && performance.now() - startGesamt > 8e3) break;
      const zeit = await new Promise((resolve) => requestAnimationFrame(resolve));
      if (vorher) frameMs.push(zeit - vorher);
      vorher = zeit;
      const vor = performance.now();
      if (vorBild) vorBild();
      updateMs.push(performance.now() - vor);
      const start = performance.now();
      renderer.render(scene2(), camera());
      renderMs.push(performance.now() - start);
    }
    const sort = (a2) => [...a2].sort((x2, y2) => x2 - y2);
    const f13 = sort(frameMs), r4 = sort(renderMs);
    const frameMittel = frameMs.reduce((a2, b4) => a2 + b4, 0) / frameMs.length;
    const extra = info ? info() : {};
    return {
      frames: renderMs.length,
      fps: runde(1e3 / frameMittel),
      frameP95Ms: runde(perzentil(f13, 0.95)),
      renderMittelMs: runde(renderMs.reduce((a2, b4) => a2 + b4, 0) / renderMs.length),
      renderP95Ms: runde(perzentil(r4, 0.95)),
      updateMittelMs: runde(updateMs.reduce((a2, b4) => a2 + b4, 0) / updateMs.length),
      frameUeber33ms: frameMs.filter((x2) => x2 > 33.4).length,
      drawCalls: renderer.info.render.calls,
      dreiecke: renderer.info.render.triangles,
      geometrien: renderer.info.memory.geometries,
      texturen: renderer.info.memory.textures,
      pixelRatio: renderer.getPixelRatio(),
      ...extra
    };
  }

